def create_monthly_plans_from_profile_price(apps, schema_editor):
    AnalystProfile = apps.get_model("cabinet", "AnalystProfile")
    AnalystPaidPlan = apps.get_model("cabinet", "AnalystPaidPlan")
    AnalystPaidSubscription = apps.get_model("cabinet", "AnalystPaidSubscription")

    for profile in AnalystProfile.objects.filter(
        paid_predictions_enabled=True,
        paid_predictions_price__gt=0,
    ).iterator():
        plan, _ = AnalystPaidPlan.objects.get_or_create(
            analyst_id=profile.user_id,
            duration_days=30,
            defaults={
                "title": "30 дней",
                "price": profile.paid_predictions_price,
                "is_active": True,
                "order": 30,
            },
        )
        AnalystPaidSubscription.objects.filter(
            analyst_id=profile.user_id,
            plan__isnull=True,
        ).update(plan=plan, duration_days=30)


